"""Train, evaluate and export the two Glassbox Tsetlin Machines.

    python glassbox/train.py                 # both models, hyperparameters from glassbox/config.json
    python glassbox/train.py --only guard    # one model
    python glassbox/train.py --tune          # grid search on the validation split (writes results/tuning_*.json)
    python glassbox/train.py --regen         # rebuild glassbox/data/*.jsonl from the generators first

Protocol (both models):
  * data: glassbox/data/{guard,router}.jsonl, generated by gbx/data_*.py (seeded);
  * split: stratified by label, seeded, train 65% / validation 15% / test 20%,
    stored in each row's "split" field;
  * vocabulary: chosen on training rows only;
  * tuning (--tune): fit on train, score on validation; the test split is never read;
  * final model: fit on train + validation with the chosen settings, literal
    pruning (gbx/pipeline.py), clauses that never fire dropped, then exactly one
    evaluation on the untouched test split and on the hand-written challenge set;
  * export: public/models/<id>.json, glassbox/results/<id>.json, glassbox/parity.json.
"""
from __future__ import annotations

import argparse
import collections
import datetime as dt
import itertools
import json
import multiprocessing as mp
import os
import platform
import random
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

from gbx import challenge, data_guard, data_router  # noqa: E402
from gbx import guard_features as GF  # noqa: E402
from gbx import router_features as RF  # noqa: E402
from gbx.pipeline import (DATA, MODELS, RESULTS, assign_splits, build_vocab, clause_stats, evaluate_exported,  # noqa: E402
                          export_clauses, matrix, metrics, simplify_clauses, read_jsonl, rule_text, sha256_file,
                          train_tm, write_jsonl)
from gbx.tm import TsetlinMachine, argmax_with_priority  # noqa: E402

SPLIT_SEED = 2026
COMMAND = "python glassbox/train.py"

SPECS = {
    "guard": {
        "id": "glassbox-guard",
        "name": "Glassbox Guard",
        "task": "Classifies a proposed agent tool call as allow, ask or block.",
        "classes": ["allow", "ask", "block"],
        "tiePriority": ["ask", "block", "allow"],
        "data": "guard.jsonl",
        "challenge": "guard_challenge.jsonl",
    },
    "router": {
        "id": "glassbox-router",
        "name": "Glassbox Router",
        "task": "Routes a chat prompt to answer, edit, run, search or research.",
        "classes": ["answer", "edit", "run", "search", "research"],
        "tiePriority": ["answer", "search", "research", "edit", "run"],
        "data": "router.jsonl",
        "challenge": "router_challenge.jsonl",
    },
}


def log(*a):
    print(*a, flush=True)


# ---------------------------------------------------------------------------- data
def ensure_data(regen: bool) -> None:
    os.makedirs(DATA, exist_ok=True)
    gpath, rpath = os.path.join(DATA, "guard.jsonl"), os.path.join(DATA, "router.jsonl")
    if regen or not os.path.exists(gpath):
        rows = data_guard.build(seed=7)
        assign_splits(rows, seed=SPLIT_SEED)
        write_jsonl(gpath, rows)
        log(f"wrote {gpath} ({len(rows)} rows)")
    if regen or not os.path.exists(rpath):
        rows = data_router.build(seed=11)
        assign_splits(rows, seed=SPLIT_SEED)
        write_jsonl(rpath, rows)
        log(f"wrote {rpath} ({len(rows)} rows)")
    write_jsonl(os.path.join(DATA, "guard_challenge.jsonl"), challenge.guard_rows())
    write_jsonl(os.path.join(DATA, "router_challenge.jsonl"), challenge.router_rows())


def featurizer(kind: str):
    return GF.GuardFeaturizer() if kind == "guard" else RF.RouterFeaturizer()


def featurize_rows(kind: str, rows: list[dict]) -> list[list[str]]:
    fz = featurizer(kind)
    if kind == "guard":
        return [fz.featurize({k: r[k] for k in ("tool", "args", "workspaceRoot") if k in r}) for r in rows]
    return [fz.featurize(r["prompt"]) for r in rows]


def vocab_for(kind: str, feats, labels, cfg) -> list[str]:
    sort_key = GF.feature_sort_key if kind == "guard" else RF.feature_sort_key
    return build_vocab(feats, labels, cfg["min_df"], cfg.get("caps", {}), sort_key)


def describe(kind: str, name: str) -> tuple[str, str]:
    return GF.describe(name) if kind == "guard" else RF.describe(name)


# ---------------------------------------------------------------------------- tuning
def _tune_one(args):
    kind, cfg = args
    spec = SPECS[kind]
    rows = read_jsonl(os.path.join(DATA, spec["data"]))
    feats = featurize_rows(kind, rows)
    classes = spec["classes"]
    prio = [classes.index(c) for c in spec["tiePriority"]]
    tr = [i for i, r in enumerate(rows) if r["split"] == "train"]
    va = [i for i, r in enumerate(rows) if r["split"] == "val"]
    vocab = vocab_for(kind, [feats[i] for i in tr], [rows[i]["label"] for i in tr], cfg)
    X = matrix(feats, vocab)
    y = np.array([classes.index(r["label"]) for r in rows])
    t0 = time.time()
    tm, curve = train_tm(X[tr], y[tr], len(classes), cfg, prio, cfg["seed"], X[va], y[va])
    lit_tr = TsetlinMachine.literals(X[tr])
    prune = simplify_clauses(tm, lit_tr, y[tr])
    lit_va = TsetlinMachine.literals(X[va])
    pruned_val = float((argmax_with_priority(tm.scores(lit_va), prio) == y[va]).mean())
    inc = tm.include_mask()
    lens = inc.sum(axis=2)
    return {"cfg": cfg, "features": len(vocab), "valCurve": curve, "bestEpoch": int(np.argmax(curve)) + 1,
            "valAtLastEpoch": curve[-1], "valAfterPruning": round(pruned_val, 4),
            "avgLiteralsAfterPruning": round(float(lens[lens > 0].mean()), 2), "pruning": prune, "seconds": round(time.time() - t0, 1)}


def tune(kind: str, base: dict, grid: dict, workers: int) -> None:
    keys = sorted(grid)
    cfgs = []
    for combo in itertools.product(*[grid[k] for k in keys]):
        c = dict(base)
        c.update(dict(zip(keys, combo)))
        cfgs.append(c)
    log(f"[{kind}] tuning {len(cfgs)} configurations on the validation split ({workers} workers)")
    out = []
    with mp.Pool(workers) as pool:
        for r in pool.imap_unordered(_tune_one, [(kind, c) for c in cfgs]):
            out.append(r)
            c = r["cfg"]
            log(f"  clauses={c['clauses']} T={c['T']} s={c['s']} negation={c['negation']}: val {max(r['valCurve']):.4f} (best epoch {r['bestEpoch']}), "
                f"after pruning {r['valAfterPruning']:.4f}, {r['avgLiteralsAfterPruning']} literals/clause, {r['seconds']}s")
    out.sort(key=lambda r: -r["valAfterPruning"])
    os.makedirs(RESULTS, exist_ok=True)
    with open(os.path.join(RESULTS, f"tuning_{kind}.json"), "w", encoding="utf-8", newline="\n") as f:
        json.dump({"note": "Validation-split results only; the test split is not read during tuning.", "runs": out}, f, indent=1)


# ---------------------------------------------------------------------------- final training
def train_final(kind: str, cfg: dict) -> dict:
    spec = SPECS[kind]
    classes = spec["classes"]
    prio = [classes.index(c) for c in spec["tiePriority"]]
    path = os.path.join(DATA, spec["data"])
    rows = read_jsonl(path)
    feats = featurize_rows(kind, rows)
    fit = [i for i, r in enumerate(rows) if r["split"] in ("train", "val")]
    test = [i for i, r in enumerate(rows) if r["split"] == "test"]
    vocab = vocab_for(kind, [feats[i] for i in fit], [rows[i]["label"] for i in fit], cfg)
    X = matrix(feats, vocab)
    y = np.array([classes.index(r["label"]) for r in rows])
    log(f"[{kind}] {len(fit)} training rows (train+val), {len(test)} test rows, {len(vocab)} features, {cfg}")

    t0 = time.time()
    tm, _ = train_tm(X[fit], y[fit], len(classes), cfg, prio, cfg["seed"])
    train_seconds = time.time() - t0
    lit_fit = TsetlinMachine.literals(X[fit])
    acc_before = float((argmax_with_priority(tm.scores(lit_fit), prio) == y[fit]).mean())
    prune = simplify_clauses(tm, lit_fit, y[fit])
    clauses, dropped = export_clauses(tm, classes, lit_fit)
    log(f"[{kind}] trained in {train_seconds:.0f}s; pruning {prune}; dropped {dropped}; {len(clauses)} clauses kept")

    features = []
    for n in vocab:
        t, ng = describe(kind, n)
        features.append({"name": n, "text": t, "neg": ng})
    stats = clause_stats(clauses)
    fz = featurizer(kind)
    model = {
        "format": "glassbox-tm/1",
        "id": spec["id"],
        "name": spec["name"],
        "task": spec["task"],
        "classes": classes,
        "tiePriority": spec["tiePriority"],
        "features": features,
        "clauses": clauses,
        "featurizer": fz.spec,
    }
    held, pred, S = evaluate_exported(model, [feats[i] for i in test], [rows[i]["label"] for i in test])
    fit_eval, _, _ = evaluate_exported(model, [feats[i] for i in fit], [rows[i]["label"] for i in fit])
    ch_rows = read_jsonl(os.path.join(DATA, spec["challenge"]))
    ch_feats = featurize_rows(kind, ch_rows)
    ch_eval, ch_pred, _ = evaluate_exported(model, ch_feats, [r["label"] for r in ch_rows])
    log(f"[{kind}] held-out accuracy {held['accuracy']:.4f} (n={held['n']}), challenge {ch_eval['accuracy']:.4f} (n={ch_eval['n']}), "
        f"train+val {fit_eval['accuracy']:.4f}")

    trained_at = dt.datetime.now(dt.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    notes = (f"Tsetlin Machine, {stats['clauses']} weighted clauses over {len(vocab)} named features. "
             f"Held-out accuracy {held['accuracy'] * 100:.1f}% on {held['n']} synthetic examples from the same templates as training; "
             f"{ch_eval['accuracy'] * 100:.1f}% on {ch_eval['n']} hand-written out-of-template examples. Prototype: trained on synthetic data.")
    model["metrics"] = {"heldOut": held, "challenge": ch_eval, "trainPlusVal": {"accuracy": fit_eval["accuracy"], "n": fit_eval["n"]}}
    model["meta"] = {
        "trainedAt": trained_at,
        "trainSize": len(fit),
        "heldOutSize": len(test),
        "challengeSize": len(ch_rows),
        "clauses": stats["clauses"],
        "avgLiterals": stats["avgLiterals"],
        "maxLiterals": stats["maxLiterals"],
        "clausesPerClass": stats["perClass"],
        "features": len(vocab),
        "datasetSha256": sha256_file(path),
        "dataset": f"glassbox/data/{spec['data']}",
        "challengeSha256": sha256_file(os.path.join(DATA, spec["challenge"])),
        "splitSeed": SPLIT_SEED,
        "command": COMMAND,
        "hyperparameters": cfg,
        "trainSeconds": round(train_seconds, 1),
        "pruning": dict(prune, droppedClauses=dropped, trainPlusValAccuracyBeforePruning=round(acc_before, 4)),
        "environment": {"python": platform.python_version(), "numpy": np.__version__},
        "notes": notes,
    }
    os.makedirs(MODELS, exist_ok=True)
    out_path = os.path.join(MODELS, f"{spec['id']}.json")
    with open(out_path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(model, f, separators=(",", ":"), ensure_ascii=True)
    log(f"[{kind}] wrote {out_path} ({os.path.getsize(out_path) / 1024:.0f} KiB)")

    # ---- report: errors, per-family accuracy, example rules
    fam_key = "family" if kind == "guard" else "template"
    fam = collections.defaultdict(lambda: [0, 0])
    errors = []
    for j, i in enumerate(test):
        ok = classes[pred[j]] == rows[i]["label"]
        fam[rows[i][fam_key]][0] += ok
        fam[rows[i][fam_key]][1] += 1
        if not ok:
            errors.append({"id": rows[i]["id"], "label": rows[i]["label"], "predicted": classes[pred[j]],
                           "scores": dict(zip(classes, S[j].tolist())),
                           "input": rows[i].get("prompt") or {k: rows[i][k] for k in ("tool", "args", "workspaceRoot") if k in rows[i]}})
    ch_errors = [{"id": r["id"], "label": r["label"], "predicted": classes[p],
                  "input": r.get("prompt") or {k: r[k] for k in ("tool", "args", "workspaceRoot") if k in r}}
                 for r, p in zip(ch_rows, ch_pred) if classes[p] != r["label"]]
    heavy = sorted(clauses, key=lambda c: -c["w"])[:25]
    report = {
        "model": spec["id"], "trainedAt": trained_at, "command": COMMAND, "metrics": model["metrics"], "meta": model["meta"],
        "perGroupHeldOutAccuracy": {k: {"correct": v[0], "n": v[1]} for k, v in sorted(fam.items())},
        "heldOutErrors": errors, "challengeErrors": ch_errors,
        "heaviestClauses": [{"id": c["id"], "weight": c["w"], "rule": rule_text(c, features)} for c in heavy],
    }
    with open(os.path.join(RESULTS, f"{spec['id']}.json"), "w", encoding="utf-8", newline="\n") as f:
        json.dump(report, f, indent=1, ensure_ascii=False)

    # ---- parity examples: 200 held-out rows, stratified, seeded
    rng = random.Random(4242)
    by = collections.defaultdict(list)
    for i in test:
        by[rows[i]["label"]].append(i)
    pick = []
    per = 200 // len(classes)
    for c in classes:
        idx = sorted(by[c])
        rng.shuffle(idx)
        pick += idx[:per]
    rest = [i for i in test if i not in set(pick)]
    rng.shuffle(rest)
    pick += rest[: 200 - len(pick)]
    em_index = {f["name"]: k for k, f in enumerate(features)}
    parity = []
    for i in sorted(pick):
        j = test.index(i)
        inp = rows[i].get("prompt") if kind == "router" else {k: rows[i][k] for k in ("tool", "args", "workspaceRoot") if k in rows[i]}
        parity.append({"id": rows[i]["id"], "input": inp, "label": rows[i]["label"],
                       "allFeatures": feats[i], "literals": [f for f in feats[i] if f in em_index],
                       "scores": S[j].tolist(), "predicted": classes[pred[j]]})
    return {"kind": kind, "parity": parity, "model": model}


