EDGE_ROUTER = ["", "   ", "\u00c9xplain caf\u00e9 \U0001F600 please?", "RUN THE TESTS!!!", "what's `npm run build`?\r\nthanks", "x" * 300,
               "\u2018quoted\u2019 \u201cdouble\u201d what's up"]


def write_parity(results: dict) -> None:
    out = {"note": "Inputs from the held-out test split (plus edge cases) with the Python featurizer's features, scores and "
                   "predictions. src/glassbox/__tests__/parity.test.mjs must reproduce every one exactly.",
           "command": COMMAND}
    for kind, r in results.items():
        model = r["model"]
        names = {f["name"] for f in model["features"]}
        from gbx.tm import ExportedModel
        em = ExportedModel(model)
        edge = []
        if kind == "guard":
            fz = GF.GuardFeaturizer()
            for c in EDGE_GUARD:
                fs = fz.featurize(c)
                s = em.scores_one(em.vector(fs))
                edge.append({"input": c, "allFeatures": fs, "literals": [f for f in fs if f in names], "scores": s,
                             "predicted": model["classes"][int(argmax_with_priority(np.array([s]), em.priority)[0])]})
        else:
            fz = RF.RouterFeaturizer()
            for p in EDGE_ROUTER:
                fs = fz.featurize(p)
                s = em.scores_one(em.vector(fs))
                edge.append({"input": p, "allFeatures": fs, "literals": [f for f in fs if f in names], "scores": s,
                             "predicted": model["classes"][int(argmax_with_priority(np.array([s]), em.priority)[0])]})
        out[kind] = {"modelId": model["id"], "classes": model["classes"], "heldOut": r["parity"], "edgeCases": edge}
    path = os.path.join(HERE, "parity.json")
    old = {}
    if os.path.exists(path) and len(results) < 2:
        with open(path, encoding="utf-8") as f:
            old = json.load(f)
    old.update(out)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(old, f, ensure_ascii=True, separators=(",", ":"))
    log(f"wrote {path}")


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--only", choices=["guard", "router"])
    ap.add_argument("--tune", action="store_true", help="grid search on the validation split instead of training final models")
    ap.add_argument("--regen", action="store_true", help="regenerate the synthetic datasets first")
    ap.add_argument("--workers", type=int, default=max(1, min(4, (os.cpu_count() or 2) // 2)))
    args = ap.parse_args()
    with open(os.path.join(HERE, "config.json"), encoding="utf-8") as f:
        config = json.load(f)
    ensure_data(args.regen)
    os.makedirs(RESULTS, exist_ok=True)
    kinds = [args.only] if args.only else ["guard", "router"]
    if args.tune:
        for k in kinds:
            tune(k, config[k]["final"], config[k]["grid"], args.workers)
        return
    results = {}
    for k in kinds:
        results[k] = train_final(k, config[k]["final"])
    write_parity(results)


if __name__ == "__main__":
    main()
